def divisor_game(n):
    dp = [False] * (n + 1)
    for i in range(2, n + 1):
        for x in range(1, i):
            if i % x == 0 and not dp[i - x]:                  # a move leading to an opponent LOSS
                dp[i] = True
                break
    return dp[n]

