public class Main {
    static boolean divisorGame(int n) {
        boolean[] dp = new boolean[n + 1];
        for (int i = 2; i <= n; i++) {
            for (int x = 1; x < i; x++) {
                if (i % x == 0 && !dp[i - x]) {                       // a move leading to an opponent LOSS
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[n];
    }
}

